    def __init__(self, polyglot, primary, address, name):
        super().__init__(polyglot, primary, address, name)
        self.device = None

    def bind(self, device):
        """Attach the backend device handle (refreshed each discovery)."""
        self.device = device

    def update(self):
        if self.device is None:
            return
        try:
            state = backend.poll_device(self.device)
        except Exception as ex:
            LOGGER.error(
                "Poll failed for {}: {}".format(self.name, ex), exc_info=True
            )
            self.setDriver("ST", 0)
            return
        for driver_id, key in self._POLL_MAP.items():
            if state.get(key) is not None:
                self.setDriver(driver_id, state[key])

    def cmd_play(self, command):
        if self.device is None:
            return
        backend.play(self.device)
        self.update()

